#include <iostream>
#include <cmath>
#include <iomanip>

int main() {
    double base = 2.0;
    double exponent = 7.0;
    double negVal = -9.8;

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "pow(2, 7) = " << std::pow(base, exponent) << "\n";
    std::cout << "floor(-9.8) = " << std::floor(negVal) << "\n";
    std::cout << "fabs(-9.8) = " << std::fabs(negVal) << "\n";
    std::cout << "fmod(2.6, 1.2) = " << std::fmod(2.6, 1.2) << "\n";
    std::cout << "sqrt(9.0) = " << std::sqrt(9.0) << "\n";
    return 0;
}

#include <iostream>
#include <string>

class GradeBook {
public:
    explicit GradeBook(std::string name) : courseName(name), maximumGrade(0) {}

    int maximum(int x, int y, int z) const {
        int maximumValue = x;
        if (y > maximumValue) {
            maximumValue = y;
        }
        if (z > maximumValue) {
            maximumValue = z;
        }
        return maximumValue;
    }

    void processGrades(int g1, int g2, int g3) {
        maximumGrade = maximum(g1, g2, g3);
        std::cout << "Course: " << courseName << "\n";
        std::cout << "Grades: " << g1 << ", " << g2 << ", " << g3 << "\n";
        std::cout << "Maximum: " << maximumGrade << "\n";
    }

private:
    std::string courseName;
    int maximumGrade;
};

int main() {
    GradeBook book("CS101 C++ Programming");
    int a = 67, b = 86, c = 75;
    book.processGrades(a, b, c);
    return 0;
}
